package fetch

import (
	"io"
	"net/http"
)

func Price(client *http.Client, sym string) (string, error) {
	resp, err := client.Get("https://markets.internal.example/quote/" + sym)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	b, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

